checks=[]
def ck(name,value,expected):
 assert value==expected,(name,value,expected);checks.append(dict(name=name,result=value,expected=expected))
ck('Softmax ln4 ln2 ln1',round(math.exp(math.log(4))/sum(math.exp(math.log(x))for x in[4,2,1]),12),round(4/7,12))
ck('Abstain below threshold',.6>=.7,False);ck('PCM byte rate',24000*16//8,48000);ck('20ms payload',48000*20//1000,960);ck('Buffer underflow milliseconds',max(0,200-120),80);ck('Old queued audio milliseconds',5*20,100)
def updates(events):
 last=None;out=[]
 for label,score in events:
  if score>=.75 and label!=last:out.append(label);last=label
 return out
ck('Deduplicated accepted updates',updates([('neutral',.8),('neutral',.9),('sad',.6),('sad',.85),('sad',.9)]),['neutral','sad'])
ck('Parallel critical path milliseconds',max(70,110)+10+180+40,340);ck('Stale label rejected',(5-4.4)<=.3,False)
size=640*480*(3+2); ck('Bytes per synchronized image pair',size,1536000);ck('Maximum whole image pair rate',int((40000000-48000)//size),26);ck('26Hz total bytes/s',26*size+48000,39984000);ck('27Hz exceeds link',27*size+48000>40000000,True);ck('Worker frames/s',1/.08,12.5);ck('Backlog growth frames/s',30-1/.08,17.5);ck('Fresh eligible labels',[i for i,(s,t)in enumerate([(.95,9.5),(.7,9.9),(.8,9.75)],1)if s>=.75 and 10-t<=.3],[3])
