 budget=rng.randrange(1,10000000);unit=rng.randrange(1,10000);n=budget//unit;assert n*unit<=budget<(n+1)*unit;assertions+=1
 buf,gap=rng.randrange(1000),rng.randrange(1000);assert min(buf,gap)+max(0,gap-buf)==gap;assertions+=1
